ROWS=[]
def add(module,title,actors,api,request,result,rules,conditional=''):
 n=sum(r['module']==module for r in ROWS)+1
 direct=actors.split(); conditional=conditional.split()
 ROWS.append(dict(id=f'{module}.{n:02}',module=module,functionality=title,actors=direct,conditional_actors=conditional,
   api=api,request=request,result=result,rules=rules,evidence=MODULES[module][2].split(';')))

